import { I18n } from 'react-i18nify-lite';

import en from './en';
import es from './es';

// Build-time check so webpack keeps only the current platform's copy.
const platform =
  process.env.REACT_APP_ONBOARDING_TYPE === 'ios'
    ? require('./ios').default
    : require('./android').default;

const initLang = () => {
  I18n.setTranslations({
    en: { ...en, ...platform.en },
    es: { ...es, ...platform.es },
  });
};

export { initLang };
