import React from "react";
import { I18n } from "react-i18nify-lite";
import CommonLogin from "../common/login";
import { sendMessageToIos } from "./commons";

export default class Login extends React.Component {
  // App Review 3.1.1: never collect credentials in-app; iOS opens the panel login in Safari.
  handleClickLogin = () => {
    sendMessageToIos("login");
  };

  handleClickQR = (event) => {
    event.preventDefault();
    sendMessageToIos("qrcode");
  };

  handleShowTerms = (event) => {
    event.preventDefault();
    sendMessageToIos("terms");
  };

  handleShowPrivacy = (event) => {
    event.preventDefault();
    sendMessageToIos("privacy");
  };

  handleWhatsPrey = (event) => {
    event.preventDefault();
    this.props.history.push(`/${I18n._locale}/whatsprey`);
  };

  render() {
    return (
      <CommonLogin
        primaryTabLabel={I18n.t("ios.signin.tab_login")}
        primaryPane={
          <div className="login-pane">
            <div className="login-pane-header"></div>
            <div className="login-pane-main">
              <button
                type="button"
                onClick={this.handleClickLogin}
                className="ob-btn login-submit-btn"
              >
                {I18n.t("signin.button_submit")}
              </button>
              <p className="login-pane-copy">{I18n.t("ios.signin.safari_hint")}</p>
            </div>
          </div>
        }
        onQr={this.handleClickQR}
        onWhatsPrey={this.handleWhatsPrey}
        onTerms={this.handleShowTerms}
        onPrivacy={this.handleShowPrivacy}
      />
    );
  }
}
